    in reverse direction:{
      tuck Front_Needles[0:width:2];
      tuck Back_Needles[1:width:2];
    }
  }

  // Knit both layers
  for _ in range(30):{
    with Sheet as s0:{
      in reverse direction:{ knit Loops; }
    }
    with Sheet as s1:{
      in reverse direction:{ knit Loops; }
    }
  }
}
cut c1;

