width = 10;

def alt_tuck_cast_on(width):{
    in Leftward direction:{
      tuck Front_Needles[0:width:2];
    }
    in reverse direction:{
      tuck Front_Needles[1:width:2];
    }
}


with Carrier as c1:{
  in Leftward direction:{
    tuck Front_Needles[1:width:2];
  }
  in reverse direction:{
    tuck Front_Needles[0:width:2];
  }

  alt_tuck_cast_on(width);
  alt_tuck_cast_on(width);

  releasehook;
  for row in range(6):{
    in reverse direction:{
      knit Loops;
    }
  }
}
cut c1;

